-- ================================================================
-- MIGRACIÓN DATOS SISTEMA ANTIGUO → SUPABASE
-- Fuente: http://3estrellasdeoro.com/sales/ (PHP/MySQL legacy)
-- Generado: 2026-08-18
-- Registros: 17,748 boletos (Mayo–Agosto 2026)
-- ================================================================
-- INSTRUCCIONES:
-- 1. Abre el Editor SQL de Supabase (SQL Editor)
-- 2. Pega y ejecuta el PASO 1 (tabla + índices)
-- 3. Ejecuta los bloques INSERT en orden
-- 4. Verifica con: SELECT COUNT(*) FROM legacy_bookings;
-- ================================================================

-- ================================================================
-- PASO 1: CREAR TABLA DE BOLETOS HISTÓRICOS
-- (tabla separada para no interferir con el sistema nuevo)
-- ================================================================
CREATE TABLE IF NOT EXISTS legacy_bookings (
  id             SERIAL PRIMARY KEY,
  ticket_id      TEXT NOT NULL UNIQUE,       -- ID del sistema antiguo (ej: 1356434)
  booking_number TEXT NOT NULL,              -- TEO + ticket_id
  origin_code    TEXT NOT NULL,              -- HUN, LAX, SYC, etc.
  destination_code TEXT NOT NULL,
  ticket_type    TEXT NOT NULL,              -- one_way / round_trip
  passenger_name TEXT NOT NULL,
  passenger_type TEXT NOT NULL DEFAULT 'adult',  -- adult / child
  travel_date    DATE NOT NULL,
  travel_time    TIME,
  amount         DECIMAL(8,2) NOT NULL,
  payment_method TEXT NOT NULL DEFAULT 'cash',
  sold_by        TEXT,                       -- username del cajero antiguo
  imported_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_legacy_bookings_date ON legacy_bookings(travel_date);
CREATE INDEX IF NOT EXISTS idx_legacy_bookings_origin ON legacy_bookings(origin_code, destination_code);
CREATE INDEX IF NOT EXISTS idx_legacy_bookings_sold_by ON legacy_bookings(sold_by);


