-- ================================================================
-- PASO 3: VERIFICACIÓN
-- ================================================================
SELECT 
  COUNT(*) as total,
  MIN(travel_date) as fecha_mas_antigua,
  MAX(travel_date) as fecha_mas_reciente,
  SUM(amount) as revenue_total_estimado
FROM legacy_bookings;

-- Por ruta:
SELECT origin_code, destination_code, COUNT(*) as boletos, SUM(amount) as revenue
FROM legacy_bookings
GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 10;

-- Por cajero:
SELECT sold_by, COUNT(*) as boletos
FROM legacy_bookings  
GROUP BY 1 ORDER BY 2 DESC;
